// Linux x86-64 no-game test for the production cache-bounds code generator.
// Windows additionally tests the production patch installer and SEH. This test executes the
// exact generated bytes, verifies register/branch behavior, and times only a synthetic wrapper.
#include "../src/render_cache_bounds.h"
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>
#include <chrono>

static int checks, failed;
static void check(bool ok, const char *label) {
    ++checks; if (!ok) { ++failed; printf("FAIL: %s\n", label); }
}
template<class T> static void store(void *p, size_t at, T v) { memcpy((char*)p + at, &v, sizeof v); }
template<class T> static T load(void *p, size_t at) { T v; memcpy(&v, (char*)p + at, sizeof v); return v; }
using Fn = int (*)(void *, uint32_t);

int main() {
    const long page = sysconf(_SC_PAGESIZE);
    if (page < 4096) return 2;
    unsigned char *mem = (unsigned char*)mmap(nullptr, page * 2, PROT_READ | PROT_WRITE,
                                               MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) return 2;
    unsigned char *fn = mem, *stub = mem + page;
    // System V arguments: RDI = renderer, ESI = slot. RDI is explicitly saved to make this
    // wrapper comparable to the Windows test; RDX is the renderer's slot register.
    unsigned char pre[] = {0x57,0x89,0xf2,0x48,0xb8,0,0,0,0,0,0,0,0};
    const uint64_t marker = 0x123456789abcdef0ull;
    memcpy(pre + 5, &marker, 8); memcpy(fn, pre, sizeof pre);
    const unsigned char site[] = {0x81,0xe2,0xff,0xff,0xff,0x00,0x48,0x8b,0x87,0x68,0x01,0x00,0x00,0x8b,0xca};
    const unsigned char next[] = {0x48,0x89,0x87,0x00,0x02,0x00,0x00,0x89,0x8f,0x08,0x02,0x00,0x00,0xb8,1,0,0,0,0x5f,0xc3};
    const unsigned char miss[] = {0x48,0x89,0x87,0x10,0x02,0x00,0x00,0x31,0xc0,0x5f,0xc3};
    const size_t nextoff = sizeof pre + sizeof site, missoff = nextoff + sizeof next;
    memcpy(fn + nextoff, next, sizeof next); memcpy(fn + missoff, miss, sizeof miss);
    alignas(4) uint32_t counter = 0;
    check(!render_cache_bounds::build(nullptr, 0, 0, 0, 0), "builder rejects null destinations");
    check(!render_cache_bounds::build(stub, render_cache_bounds::k_size - 1, 1, 1, 1), "builder rejects short output");
    check(!render_cache_bounds::build(stub, render_cache_bounds::k_size, 0, 1, 1), "builder rejects null jump");
    check(render_cache_bounds::build(stub, render_cache_bounds::k_size, (uintptr_t)(fn + nextoff),
                                     (uintptr_t)(fn + missoff), (uintptr_t)&counter), "production stub generated");
    unsigned char patch[15] = {0xff,0x25,0,0,0,0};
    memcpy(patch + 6, &stub, 8); patch[14] = 0x90;
    memcpy(fn + sizeof pre, patch, sizeof patch);
    if (mprotect(mem, page * 2, PROT_READ | PROT_EXEC)) return 2;
    __builtin___clear_cache((char*)mem, (char*)mem + page * 2);
    Fn call = (Fn)fn;
    alignas(16) unsigned char renderer[0x220] = {};
    const uint64_t pool = 0x56789000;
    store(renderer, 0x168, pool); store(renderer, 0x174, (uint32_t)3); store(renderer, 0x178, (uint32_t)4);
    check(call(renderer, 0) == 1 && load<uint64_t>(renderer, 0x200) == pool && load<uint32_t>(renderer, 0x208) == 0 && counter == 0,
          "valid first slot preserves displaced MOV results");
    check(call(renderer, 2) == 1 && load<uint32_t>(renderer, 0x208) == 2 && counter == 0, "last live slot accepted");
    check(call(renderer, 3) == 0 && counter == 1 && load<uint64_t>(renderer, 0x210) == marker, "count boundary rejected and RAX restored");
    store(renderer, 0x174, (uint32_t)5); store(renderer, 0x178, (uint32_t)2);
    check(call(renderer, 2) == 0 && counter == 2, "capacity boundary rejected");
    store(renderer, 0x174, (uint32_t)3); store(renderer, 0x178, (uint32_t)4);
    check(call(renderer, 0xab000001) == 1 && load<uint32_t>(renderer, 0x208) == 1, "mask matches original code");
    check(call(renderer, 0xffffffff) == 0 && counter == 3, "masked large slot rejected");
    store(renderer, 0x168, (uint64_t)0x12345000);
    check(call(renderer, 1) == 1 && load<uint64_t>(renderer, 0x200) == 0x12345000, "invalid pool ownership is not detected");
    store(renderer, 0x168, pool);
    const unsigned loops = 2000000;
    volatile int sink = 0;
    auto before = std::chrono::steady_clock::now();
    for (unsigned i = 0; i < loops; ++i) sink += call(renderer, 1);
    auto elapsed = std::chrono::duration<double, std::nano>(std::chrono::steady_clock::now() - before).count();
    check(sink == (int)loops, "benchmark exercised valid branch");
    printf("cache bounds native synthetic: %.1f ns/call (%u calls, wrapper included; not FPS)\n", elapsed / loops, loops);
    printf("cache bounds native selftest: %d checks, %d failed\n", checks, failed);
    munmap(mem, page * 2);
    return failed ? 1 : 0;
}
